package com.stange.safebridge;
import android.Manifest;import android.app.Activity;import android.app.AlertDialog;import android.os.Bundle;import android.view.WindowManager;import android.webkit.*;import android.widget.*;import android.net.Uri;import java.io.ByteArrayInputStream;
/** Isolated same-origin map viewer. No live-session tokens, JS bridge or file access. */
public final class NearbyMapActivity extends Activity {
 private WebView web;private boolean consent=false,visible=false,autoOpen=false,openPending=false;private TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(16,16,16,16);status=new TextView(this);status.setTextSize(17);status.setText(NearbyMapConfig.configured()?"Nearby police, hospitals, Wi-Fi and public phones. Listings cannot establish safety or availability.":"Nearby map is not configured in this test build. No location is requested or sent. An approved hosted service and map-data provider are required. Snapshots remain available.");layout.addView(status);Button open=new Button(this);open.setText("Open nearby map");open.setEnabled(NearbyMapConfig.configured());layout.addView(open);open.setOnClickListener(v->confirm());Button close=new Button(this);close.setText("Close and clear map");layout.addView(close);close.setOnClickListener(v->{clear();finish();});web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setGeolocationEnabled(true);s.setSaveFormData(false);s.setSupportMultipleWindows(false);CookieManager.getInstance().setAcceptCookie(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
 web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView w,String url){if(autoOpen&&visible&&consent&&allowed(Uri.parse(url))&&"/nearby/index.html".equals(Uri.parse(url).getPath())){autoOpen=false;if(LocationSnapshot.hasPermission(NearbyMapActivity.this))w.evaluateJavascript("document.getElementById('open')?.click()",null);}}@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !allowed(r.getUrl());}@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){if(!allowed(r.getUrl()))return NearbyMapResource.blocked();if("GET".equals(r.getMethod()))return NearbyMapResource.get(r.getUrl().toString());return "POST".equals(r.getMethod())?null:NearbyMapResource.blocked();}@Override public void onReceivedSslError(WebView w,SslErrorHandler h,android.net.http.SslError e){h.cancel();}@Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())status.setText("Map unavailable. Current nearby results cannot be confirmed.");}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback callback){callback.invoke(origin,visible&&consent&&sameOrigin(origin)&&LocationSnapshot.hasPermission(NearbyMapActivity.this),false);}@Override public void onPermissionRequest(PermissionRequest r){r.deny();}});layout.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);}
 private boolean sameOrigin(String value){try{return NearbyMapConfig.origin().equals(LiveConfig.checkedEndpoint(value));}catch(Exception e){return false;}}
 private boolean allowed(Uri u){if(u==null||!"https".equals(u.getScheme())||u.getUserInfo()!=null||u.getEncodedFragment()!=null)return false;return sameOrigin("https://"+u.getEncodedAuthority());}
 private void confirm(){if(!NearbyMapConfig.configured())return;new AlertDialog.Builder(this).setTitle("Allow map service access?").setMessage(NearbyMapConfig.PROVIDER_DISCLOSURE+"\n\nThe service receives your network address. After location permission, your search location goes to its map-data provider. All four categories are searched together. Provider records may remain. Closing clears this view, not records already received. No live-sharing link/token is sent.").setNegativeButton("Cancel",null).setPositiveButton("Allow and open",(d,w)->{consent=true;if(!LocationSnapshot.hasPermission(this))requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},420);else load();}).show();}
 private void load(){if(!consent||!NearbyMapConfig.configured()){openPending=false;return;}if(!visible){openPending=true;return;}openPending=false;autoOpen=true;web.loadUrl(NearbyMapConfig.origin()+"/nearby/index.html");status.setText("Choose automatic device location or a manual area. No background tracking is started.");}
 @Override public void onRequestPermissionsResult(int code,String[] p,int[] g){super.onRequestPermissionsResult(code,p,g);if(code==420&&consent){load();if(!LocationSnapshot.hasPermission(this))status.setText("Location permission unavailable. Use the map's manual area.");}}
 private void clear(){consent=false;autoOpen=false;openPending=false;NearbyMapResource.cancelAll();if(web!=null){web.stopLoading();web.loadUrl("about:blank");web.clearHistory();web.clearFormData();web.clearCache(true);}GeolocationPermissions.getInstance().clearAll();}
 @Override protected void onResume(){super.onResume();visible=true;if(web!=null)web.onResume();if(openPending&&consent)load();}
 @Override protected void onPause(){visible=false;super.onPause();}
 @Override protected void onStop(){visible=false;clear();if(web!=null)web.onPause();super.onStop();}
 @Override protected void onDestroy(){clear();if(web!=null){web.destroy();web=null;}super.onDestroy();}
}
